-- 013_wv_landing_atlas.sql — the landing atlas (the sky, its constellations,
-- the worldview graph and the Revelation scene), as data.
--
-- It used to ship inside the web app (core/atlas/atlas.data.ts and
-- assets/data/worldview-graph.json). Now the worker serves it at
-- GET /wv/landing-atlas and the app draws what it is given.
--
-- One row per thing drawn, by section:
--   graph       the graph's id and meta (one row)
--   cluster     a worldview cluster (territory)          AtlasCluster
--   node        a concept / claim / evidence star       AtlasNode
--   edge        a typed link between two nodes           AtlasEdge
--   view        a zoom view                              AtlasZoomView
--   layer       a sky constellation, with its sky meta   AtlasConstellationLayer
--   era         a history era for the waypoints          HistoricalEra
--   scene       the Revelation scene's head (one row)
--   scene_ring / scene_node / scene_link — its rings, nodes and links
-- sort_order keeps the order the app drew them in.
--
-- Additive and idempotent: CREATE … IF NOT EXISTS, INSERT OR REPLACE.

CREATE TABLE IF NOT EXISTS wv_landing_atlas_item (
  atlas_id    TEXT NOT NULL DEFAULT 'landing',
  section     TEXT NOT NULL,
  item_id     TEXT NOT NULL,
  sort_order  INTEGER NOT NULL DEFAULT 0,
  data_json   TEXT NOT NULL,
  updated_at  TEXT NOT NULL DEFAULT (datetime('now')),
  PRIMARY KEY (atlas_id, section, item_id)
);

CREATE INDEX IF NOT EXISTS idx_wv_landing_atlas_item_order
  ON wv_landing_atlas_item(atlas_id, section, sort_order);


