  ('landing', 'scene_ring', 'prophets', 4, '{"id":"prophets","label":"Prophetic Constellation","radius":470,"color":"#b8f0d9","opacity":0.26,"halo":40,"labelAngle":2.8902652413026098,"labelOffset":30}'),
  ('landing', 'scene_ring', 'meanings', 5, '{"id":"meanings","label":"Guidance and Meaning","radius":596,"color":"#9fe5ff","opacity":0.22,"halo":34,"labelAngle":3.581415625092364,"labelOffset":30}'),
  ('landing', 'scene_ring', 'human-drama', 6, '{"id":"human-drama","label":"Human Response","radius":736,"color":"#f0c98f","opacity":0.2,"halo":30,"labelAngle":0.9424777960769379,"labelOffset":30}'),
  ('landing', 'scene_ring', 'opposition', 7, '{"id":"opposition","label":"Whisper Network","radius":864,"color":"#c86b70","opacity":0.18,"halo":26,"labelAngle":1.5707963267948966,"labelOffset":46}'),
  ('landing', 'scene_ring', 'worldview', 8, '{"id":"worldview","label":"Worldview Constellations","radius":1080,"color":"#89b7ff","opacity":0.14,"halo":20,"labelAngle":3.518583772020569,"labelOffset":34}'),
  ('landing', 'scene_node', 'divine_allah', 0, '{"id":"divine_allah","label":"Allah","label_ar":"الله","type":"divine_center","symbolic_role":"Ontological source and supreme center","theological_weight":10,"visual_tier":0,"luminosity":10,"ring":"divine","orbit_priority":0,"angle":0,"meaning_summary":"The absolute source of being, mercy, command, judgment, and guidance. All rings take their coherence from this center.","polarity":"guidance","relation_to_center":"Self-identical center of the whole atlas.","relation_to_quran":"The Qur’an is the revealed address proceeding from this center.","relation_to_human_response":"Human life is judged by nearness, obedience, gratitude, remembrance, and repentance before this reality.","color":"#fff8df","glow":220}'),
  ('landing', 'scene_node', 'revelation_quran', 1, '{"id":"revelation_quran","label":"Qur’an","label_ar":"القرآن","type":"revelation_core","symbolic_role":"Primary revealed core","theological_weight":9.8,"visual_tier":1,"luminosity":9.6,"ring":"revelation-core","orbit_priority":1,"angle":1.5707963267948966,"meaning_summary":"The central revealed star of guidance, criterion, remembrance, mercy, and moral formation.","polarity":"guidance","relation_to_center":"Receives, discloses, and transmits divine guidance.","relation_to_quran":"It is itself the revelation core.","relation_to_human_response":"Invites recitation, reflection, obedience, reform, and communal ordering.","color":"#d9f6ff","glow":148}'),
  ('landing', 'scene_node', 'attr_rahman', 2, '{"id":"attr_rahman","label":"Mercy","label_ar":"الرحمن","type":"attribute","symbolic_role":"Merciful overflowing source","theological_weight":8.8,"visual_tier":2,"luminosity":8.4,"ring":"attributes","orbit_priority":1,"angle":-2.16,"meaning_summary":"Mercy frames existence, revelation, repentance, and return.","polarity":"guidance","relation_to_center":"A principal disclosure of the divine center.","relation_to_quran":"The Qur’an names and narrates mercy repeatedly as an interpretive key.","relation_to_human_response":"Calls humans to compassion, patience, and restoration.","color":"#f8e8bb","glow":52}'),
  ('landing', 'scene_node', 'attr_haqq', 3, '{"id":"attr_haqq","label":"Truth","label_ar":"الحق","type":"attribute","symbolic_role":"True and unshakable reality","theological_weight":8.4,"visual_tier":2,"luminosity":8,"ring":"attributes","orbit_priority":2,"angle":-1.78,"meaning_summary":"Truth grounds judgment, knowledge, revelation, and witness.","polarity":"guidance","relation_to_center":"Truth belongs to the center and stabilizes every other relation.","relation_to_quran":"The Qur’an presents itself as truth and criterion.","relation_to_human_response":"Demands honesty, testimony, and moral seriousness.","color":"#f3dfab","glow":46}'),
  ('landing', 'scene_node', 'attr_nur', 4, '{"id":"attr_nur","label":"Light","label_ar":"النور","type":"attribute","symbolic_role":"Illumining presence","theological_weight":8.2,"visual_tier":2,"luminosity":8.2,"ring":"attributes","orbit_priority":3,"angle":-1.38,"meaning_summary":"Light clarifies truth, direction, and the difference between guidance and confusion.","polarity":"guidance","relation_to_center":"A radiant disclosure of divine nearness and intelligibility.","relation_to_quran":"The Qur’an operates as light in speech, law, and remembrance.","relation_to_human_response":"Calls the human self out of heedlessness and obscurity.","color":"#ffefc4","glow":48}'),
  ('landing', 'scene_node', 'attr_hakim', 5, '{"id":"attr_hakim","label":"Wisdom","label_ar":"الحكيم","type":"attribute","symbolic_role":"Wise ordering of creation and command","theological_weight":8.3,"visual_tier":2,"luminosity":7.8,"ring":"attributes","orbit_priority":4,"angle":-0.96,"meaning_summary":"Wisdom orders revelation, prophecy, law, creation, and consequence.","polarity":"guidance","relation_to_center":"Expresses measure, order, and purposeful relation.","relation_to_quran":"The Qur’an presents itself as wise remembrance and clear explanation.","relation_to_human_response":"Calls for discernment, restraint, and right judgment.","color":"#f2db9a","glow":44}'),
  ('landing', 'scene_node', 'attr_adl', 6, '{"id":"attr_adl","label":"Justice","label_ar":"العدل","type":"attribute","symbolic_role":"Moral weight and balance","theological_weight":8.4,"visual_tier":2,"luminosity":7.9,"ring":"attributes","orbit_priority":5,"angle":-0.58,"meaning_summary":"Justice binds command, measure, witness, and accountability.","polarity":"guidance","relation_to_center":"Derives directly from divine sovereignty and wisdom.","relation_to_quran":"The Qur’an sends justice outward into law, governance, trade, and testimony.","relation_to_human_response":"Demands fairness, truth, trust, and protection of the weak.","color":"#f1d594","glow":42}'),
  ('landing', 'scene_node', 'book_torah', 7, '{"id":"book_torah","label":"Torah","label_ar":"التوراة","type":"book","symbolic_role":"Major revealed book of command and covenant","theological_weight":7.6,"visual_tier":3,"luminosity":7.4,"ring":"books","orbit_priority":1,"angle":3.078760800517997,"meaning_summary":"A major book of law, covenant, memory, and prophetic history.","polarity":"guidance","relation_to_center":"Receives authority from the divine center.","relation_to_quran":"The Qur’an confirms, recalls, and repositions it within final revelation.","relation_to_human_response":"Calls for obedience, memory, law, and communal fidelity.","color":"#f4e0b8","glow":50}'),
  ('landing', 'scene_node', 'book_psalms', 8, '{"id":"book_psalms","label":"Psalms","label_ar":"الزبور","type":"book","symbolic_role":"Book of praise and supplication","theological_weight":6.9,"visual_tier":3,"luminosity":6.8,"ring":"books","orbit_priority":2,"angle":-1.12,"meaning_summary":"A revealed stream of praise, devotion, lament, and kingship.","polarity":"guidance","relation_to_center":"Returns speech back toward the source in gratitude and praise.","relation_to_quran":"The Qur’an receives it as part of the revealed continuum.","relation_to_human_response":"Forms gratitude, humility, praise, and supplication.","color":"#d7ecff","glow":38}'),
  ('landing', 'scene_node', 'book_gospel', 9, '{"id":"book_gospel","label":"Gospel","label_ar":"الإنجيل","type":"book","symbolic_role":"Book of mercy, renewal, and witness","theological_weight":7.2,"visual_tier":3,"luminosity":7,"ring":"books","orbit_priority":3,"angle":0.16,"meaning_summary":"A revealed book associated with mercy, spirit, witness, and renewal.","polarity":"guidance","relation_to_center":"Receives light and authority from the same source.","relation_to_quran":"The Qur’an confirms its revelatory origin while correcting distortion and forgetfulness.","relation_to_human_response":"Calls for faithfulness, mercy, and humility before revelation.","color":"#f0dfcf","glow":44}'),
  ('landing', 'scene_node', 'book_scrolls', 10, '{"id":"book_scrolls","label":"Scrolls","label_ar":"الصحف","type":"book","symbolic_role":"Earlier scroll traditions","theological_weight":6.4,"visual_tier":3,"luminosity":6.2,"ring":"books","orbit_priority":4,"angle":-2.22,"meaning_summary":"Earlier scriptural scrolls associated with primordial warning, guidance, and wisdom.","polarity":"guidance","relation_to_center":"Earlier emissions from the same revelatory source.","relation_to_quran":"The Qur’an gathers them into a final horizon of remembrance and confirmation.","relation_to_human_response":"Signals continuity of responsibility across history.","color":"#e0d5c3","glow":32}'),
  ('landing', 'scene_node', 'prophet_adam', 11, '{"id":"prophet_adam","label":"Adam","label_ar":"آدم","type":"prophet","symbolic_role":"Origin of human vocation","theological_weight":7.1,"visual_tier":4,"luminosity":6.6,"ring":"prophets","orbit_priority":1,"angle":3.392920065876977,"meaning_summary":"The human beginning, entrusted with knowledge, responsibility, fall, and repentance.","polarity":"restoration","relation_to_center":"Created and taught directly from the center.","relation_to_quran":"The Qur’an retells Adam as origin of human trust, knowledge, and warning.","relation_to_human_response":"Models weakness, repentance, and recoverable dignity.","color":"#d7efc8","glow":36}'),
  ('landing', 'scene_node', 'prophet_nuh', 12, '{"id":"prophet_nuh","label":"Nuh","label_ar":"نوح","type":"prophet","symbolic_role":"Witness against civilizational corruption","theological_weight":7.3,"visual_tier":4,"luminosity":6.8,"ring":"prophets","orbit_priority":2,"angle":3.8327430373795477,"meaning_summary":"Long patience, warning, and the testing of faith against entrenched corruption.","polarity":"warning","relation_to_center":"Warns against refusal of the center.","relation_to_quran":"The Qur’an uses Nuh as a mirror for prophetic endurance.","relation_to_human_response":"Calls to patience, obedience, and refusal of mockery.","color":"#cdebc0","glow":38}'),
  ('landing', 'scene_node', 'prophet_ibrahim', 13, '{"id":"prophet_ibrahim","label":"Ibrahim","label_ar":"إبراهيم","type":"prophet","symbolic_role":"Axis of covenant, surrender, and house-building","theological_weight":8.2,"visual_tier":4,"luminosity":7.6,"ring":"prophets","orbit_priority":3,"angle":4.209734155810323,"meaning_summary":"A central patriarch of surrender, covenant, hospitality, and destruction of idols.","polarity":"guidance","relation_to_center":"Turns radically toward the center against idolatry.","relation_to_quran":"The Qur’an repeatedly reclaims Ibrahim as an exemplar of pure monotheism.","relation_to_human_response":"Calls for sacrifice, trust, migration, and rejection of idols.","color":"#dff8d1","glow":48}'),
  ('landing', 'scene_node', 'prophet_musa', 14, '{"id":"prophet_musa","label":"Musa","label_ar":"موسى","type":"prophet","symbolic_role":"Liberator, law-bearer, and challenger of empire","theological_weight":8.4,"visual_tier":4,"luminosity":7.8,"ring":"prophets","orbit_priority":4,"angle":4.900884539600077,"meaning_summary":"A major prophetic figure of law, confrontation with tyranny, covenant, and communal struggle.","polarity":"guidance","relation_to_center":"Receives command, law, and speech under divine protection.","relation_to_quran":"Most frequently narrated prophetic history in the Qur’an.","relation_to_human_response":"Calls for courage, justice, patience, and refusal of Pharaoh-like domination.","color":"#e5fcd7","glow":54}'),
  ('landing', 'scene_node', 'prophet_dawud', 15, '{"id":"prophet_dawud","label":"Dawud","label_ar":"داود","type":"prophet","symbolic_role":"Praise, kingship, and just rule","theological_weight":7.4,"visual_tier":4,"luminosity":7,"ring":"prophets","orbit_priority":5,"angle":0.92,"meaning_summary":"A prophet-king of praise, judgment, craft, and disciplined rule.","polarity":"guidance","relation_to_center":"Receives both kingdom and song under divine judgment.","relation_to_quran":"The Qur’an binds Dawud to praise, justice, and tested authority.","relation_to_human_response":"Calls rulers to humility, balance, and remembrance.","color":"#c8ebb7","glow":40}'),
  ('landing', 'scene_node', 'prophet_isa', 16, '{"id":"prophet_isa","label":"Isa","label_ar":"عيسى","type":"prophet","symbolic_role":"Mercy, sign, and witness","theological_weight":8,"visual_tier":4,"luminosity":7.4,"ring":"prophets","orbit_priority":6,"angle":0.24,"meaning_summary":"A prophet of mercy, healing, sign, spirit, and contested interpretation.","polarity":"guidance","relation_to_center":"A sign and servant, not a rival center.","relation_to_quran":"The Qur’an honors Isa while correcting theological excess.","relation_to_human_response":"Calls to humility, mercy, and truthful witness.","color":"#d9f7cb","glow":46}');

INSERT OR REPLACE INTO wv_landing_atlas_item (atlas_id, section, item_id, sort_order, data_json) VALUES
  ('landing', 'scene_node', 'prophet_muhammad', 17, '{"id":"prophet_muhammad","label":"Muhammad","label_ar":"محمد","type":"prophet","symbolic_role":"Seal of prophetic witness","theological_weight":8.8,"visual_tier":4,"luminosity":8.2,"ring":"prophets","orbit_priority":7,"angle":1.5707963267948966,"radius_offset":-38,"meaning_summary":"The final prophetic witness through whom the Qur’an enters history as recitation, law, mercy, and civilizational formation.","polarity":"guidance","relation_to_center":"Receives and transmits revelation without rivaling the center.","relation_to_quran":"Bearer, reciter, teacher, and exemplar of Qur’anic formation.","relation_to_human_response":"Calls to sincerity, mercy, courage, trustworthiness, and disciplined community.","color":"#f1ffe4","glow":66}'),
  ('landing', 'scene_node', 'meaning_guidance', 18, '{"id":"meaning_guidance","label":"Guidance","label_ar":"هدى","type":"moral_theme","symbolic_role":"Right direction","theological_weight":7.8,"visual_tier":5,"luminosity":7.4,"ring":"meanings","orbit_priority":1,"angle":4.649557127312894,"meaning_summary":"Guidance orders life toward truth, worship, justice, and flourishing under revelation.","polarity":"guidance","relation_to_center":"Flows from the center into history.","relation_to_quran":"The Qur’an names itself guidance for those who respond.","relation_to_human_response":"Requires hearing, obedience, trust, and endurance.","color":"#bdeeff","glow":40}'),
  ('landing', 'scene_node', 'meaning_mercy', 19, '{"id":"meaning_mercy","label":"Mercy","type":"moral_theme","symbolic_role":"Softening and restoration","theological_weight":7.4,"visual_tier":5,"luminosity":7,"ring":"meanings","orbit_priority":2,"angle":3.958406743523139,"meaning_summary":"Mercy interrupts despair and reopens the possibility of return.","polarity":"restoration","relation_to_center":"A descending sign of divine generosity.","relation_to_quran":"The Qur’an embodies mercy in law, story, warning, and hope.","relation_to_human_response":"Calls for care, gentleness, forgiveness, and repair.","color":"#cff7ff","glow":36}'),
  ('landing', 'scene_node', 'meaning_truth', 20, '{"id":"meaning_truth","label":"Truth","type":"moral_theme","symbolic_role":"Criterion against distortion","theological_weight":7.2,"visual_tier":5,"luminosity":6.8,"ring":"meanings","orbit_priority":3,"angle":3.204424506661589,"meaning_summary":"Truth establishes witness, judgment, and fidelity against distortion.","polarity":"guidance","relation_to_center":"Anchored directly in divine reality.","relation_to_quran":"The Qur’an functions as criterion and clarification.","relation_to_human_response":"Demands witness, honesty, and refusal of self-deception.","color":"#c4efff","glow":34}'),
  ('landing', 'scene_node', 'meaning_justice', 21, '{"id":"meaning_justice","label":"Justice","type":"moral_theme","symbolic_role":"Balance in human ordering","theological_weight":7.4,"visual_tier":5,"luminosity":6.8,"ring":"meanings","orbit_priority":4,"angle":0.76,"meaning_summary":"Justice turns transcendence into worldly accountability.","polarity":"guidance","relation_to_center":"A worldly echo of divine balance.","relation_to_quran":"The Qur’an extends justice into law, trade, testimony, and governance.","relation_to_human_response":"Requires courage, fairness, and moral cost-bearing.","color":"#bfe6ff","glow":34}'),
  ('landing', 'scene_node', 'meaning_remembrance', 22, '{"id":"meaning_remembrance","label":"Remembrance","label_ar":"ذكر","type":"moral_theme","symbolic_role":"Keeping the heart awake","theological_weight":7.1,"visual_tier":5,"luminosity":6.6,"ring":"meanings","orbit_priority":5,"angle":0.44,"meaning_summary":"Remembrance resists the drift into forgetfulness, pride, and distraction.","polarity":"restoration","relation_to_center":"Turns the self back toward the source.","relation_to_quran":"The Qur’an is itself remembrance and calls to remembrance.","relation_to_human_response":"Requires prayer, recitation, gratitude, and disciplined attention.","color":"#bee8ff","glow":34}'),
  ('landing', 'scene_node', 'meaning_wisdom', 23, '{"id":"meaning_wisdom","label":"Wisdom","type":"moral_theme","symbolic_role":"Right placing of things","theological_weight":7,"visual_tier":5,"luminosity":6.5,"ring":"meanings","orbit_priority":6,"angle":0.08,"meaning_summary":"Wisdom unites knowledge, timing, speech, and judgment.","polarity":"guidance","relation_to_center":"Reflects order already present in creation and command.","relation_to_quran":"The Qur’an teaches wise orientation rather than raw data.","relation_to_human_response":"Demands maturity, discernment, and humility.","color":"#b9dcff","glow":32}'),
  ('landing', 'scene_node', 'meaning_light', 24, '{"id":"meaning_light","label":"Light","type":"moral_theme","symbolic_role":"Visible intelligibility","theological_weight":7,"visual_tier":5,"luminosity":6.8,"ring":"meanings","orbit_priority":7,"angle":-0.24,"meaning_summary":"Light differentiates clarity from shadow, sincerity from concealment.","polarity":"guidance","relation_to_center":"Radiance from the center into human seeing.","relation_to_quran":"The Qur’an illuminates what worldly power often obscures.","relation_to_human_response":"Calls for awakened perception and honest sight.","color":"#d3f7ff","glow":34}'),
  ('landing', 'scene_node', 'drama_covenant', 25, '{"id":"drama_covenant","label":"Covenant","type":"covenant_theme","symbolic_role":"Binding relation","theological_weight":6.8,"visual_tier":6,"luminosity":6.3,"ring":"human-drama","orbit_priority":1,"angle":4.272566008882119,"meaning_summary":"Covenant binds revelation to responsibility across generations.","polarity":"guidance","relation_to_center":"A bond instituted from above.","relation_to_quran":"The Qur’an recalls broken and renewed covenants repeatedly.","relation_to_human_response":"Demands loyalty, memory, and truthful action.","color":"#f3d3a0","glow":28}'),
  ('landing', 'scene_node', 'drama_obedience', 26, '{"id":"drama_obedience","label":"Obedience","type":"moral_theme","symbolic_role":"Active submission","theological_weight":6.8,"visual_tier":6,"luminosity":6.2,"ring":"human-drama","orbit_priority":2,"angle":3.64424747816416,"meaning_summary":"Obedience turns hearing into embodied order.","polarity":"guidance","relation_to_center":"A proper response to command and mercy.","relation_to_quran":"The Qur’an repeatedly joins hearing to obeying.","relation_to_human_response":"Calls for trust, discipline, and sacrifice.","color":"#f1cc95","glow":28}'),
  ('landing', 'scene_node', 'drama_gratitude', 27, '{"id":"drama_gratitude","label":"Gratitude","type":"moral_theme","symbolic_role":"Acknowledgment of gift","theological_weight":6.5,"visual_tier":6,"luminosity":6,"ring":"human-drama","orbit_priority":3,"angle":3.078760800517997,"meaning_summary":"Gratitude names creation and revelation as gift rather than entitlement.","polarity":"restoration","relation_to_center":"Recognizes the source without self-inflation.","relation_to_quran":"The Qur’an binds gratitude to increase and ingratitude to loss.","relation_to_human_response":"Forms humility, praise, and stewardship.","color":"#f5d8a7","glow":26}'),
  ('landing', 'scene_node', 'drama_struggle', 28, '{"id":"drama_struggle","label":"Struggle","type":"moral_theme","symbolic_role":"Testing and exertion","theological_weight":6.7,"visual_tier":6,"luminosity":6.1,"ring":"human-drama","orbit_priority":4,"angle":2.57610597594363,"meaning_summary":"Struggle marks the field where guidance meets resistance and sacrifice.","polarity":"warning","relation_to_center":"A testing within the moral order set by the center.","relation_to_quran":"The Qur’an frames struggle inwardly and outwardly under discipline.","relation_to_human_response":"Calls for courage, patience, and sincerity.","color":"#eec78e","glow":26}'),
  ('landing', 'scene_node', 'drama_repentance', 29, '{"id":"drama_repentance","label":"Repentance","type":"moral_theme","symbolic_role":"Return after failure","theological_weight":6.9,"visual_tier":6,"luminosity":6.4,"ring":"human-drama","orbit_priority":5,"angle":1.9477874452256718,"meaning_summary":"Repentance reopens nearness after sin, heedlessness, and fracture.","polarity":"restoration","relation_to_center":"A re-turn toward the source.","relation_to_quran":"The Qur’an repeatedly opens the door of return.","relation_to_human_response":"Requires honesty, remorse, repair, and changed direction.","color":"#f1d1a1","glow":28}'),
  ('landing', 'scene_node', 'drama_corruption', 30, '{"id":"drama_corruption","label":"Corruption","type":"moral_theme","symbolic_role":"Decay of trust and measure","theological_weight":6.6,"visual_tier":6,"luminosity":5.7,"ring":"human-drama","orbit_priority":6,"angle":1.382300767579509,"meaning_summary":"Corruption names distortion of balance, covenant, power, and desire.","polarity":"warning","relation_to_center":"A departure from the ordering of the center.","relation_to_quran":"The Qur’an condemns corruption in land, trade, governance, and soul.","relation_to_human_response":"Warns against pride, greed, deceit, and violence.","color":"#d7a56d","glow":24}'),
  ('landing', 'scene_node', 'drama_forgetfulness', 31, '{"id":"drama_forgetfulness","label":"Forgetfulness","type":"moral_theme","symbolic_role":"Loss of orientation","theological_weight":6.4,"visual_tier":6,"luminosity":5.8,"ring":"human-drama","orbit_priority":7,"angle":0.8168140899333463,"meaning_summary":"Forgetfulness dissolves memory, gratitude, and covenant into habitless drift.","polarity":"warning","relation_to_center":"A dimming of relation to the source.","relation_to_quran":"The Qur’an diagnoses forgetting as a spiritual and civilizational danger.","relation_to_human_response":"Calls for dhikr, study, prayer, and moral wakefulness.","color":"#d9b07f","glow":24}'),
  ('landing', 'scene_node', 'opposition_iblis', 32, '{"id":"opposition_iblis","label":"Iblis","label_ar":"إبليس","type":"opposition_core","symbolic_role":"Broken anti-center","theological_weight":3.4,"visual_tier":7,"luminosity":3.2,"ring":"opposition","orbit_priority":1,"angle":1.5707963267948966,"meaning_summary":"A lower, unstable anti-center of pride, refusal, envy, whispering, and parasitic distortion.","polarity":"corruption","relation_to_center":"Defined by refusal of the center, never equal to it.","relation_to_quran":"The Qur’an reveals Iblis as tempter, deceiver, and sworn enemy.","relation_to_human_response":"Warns humans against arrogance, despair, rebellion, and whisper-led desire.","color":"#ba6268","glow":34}'),
  ('landing', 'scene_node', 'vector_temptation', 33, '{"id":"vector_temptation","label":"Temptation","type":"corruption_vector","symbolic_role":"Seductive pull","theological_weight":3.1,"visual_tier":7,"luminosity":2.8,"ring":"opposition","orbit_priority":2,"angle":1.1938052083641213,"meaning_summary":"Temptation works through nearness, appetite, and false ease.","polarity":"corruption","relation_to_center":"A lure away from the center.","relation_to_quran":"The Qur’an names temptation as a testing field requiring vigilance.","relation_to_human_response":"Calls for restraint, remembrance, and refusal.","color":"#b25a5d","glow":24}'),
  ('landing', 'scene_node', 'vector_pride', 34, '{"id":"vector_pride","label":"Pride","type":"corruption_vector","symbolic_role":"Inflated selfhood","theological_weight":3,"visual_tier":7,"luminosity":2.7,"ring":"opposition","orbit_priority":3,"angle":1.5079644737231006,"meaning_summary":"Pride resists command and refuses creaturely place.","polarity":"corruption","relation_to_center":"A refusal to bow before truth.","relation_to_quran":"The Qur’an makes pride central to satanic revolt and tyrannical rule.","relation_to_human_response":"Warns against vanity, contempt, and hard-heartedness.","color":"#aa5357","glow":22}'),
  ('landing', 'scene_node', 'vector_rebellion', 35, '{"id":"vector_rebellion","label":"Rebellion","type":"corruption_vector","symbolic_role":"Will against command","theological_weight":3.2,"visual_tier":7,"luminosity":2.8,"ring":"opposition","orbit_priority":4,"angle":1.7592918860102844,"meaning_summary":"Rebellion hardens refusal into identity and system.","polarity":"corruption","relation_to_center":"Opposes order from below.","relation_to_quran":"The Qur’an ties rebellion to denial, oppression, and heedlessness.","relation_to_human_response":"Warns against normalizing transgression.","color":"#a34d51","glow":22}'),
  ('landing', 'scene_node', 'vector_distortion', 36, '{"id":"vector_distortion","label":"Distortion","type":"corruption_vector","symbolic_role":"Bent interpretation","theological_weight":3.1,"visual_tier":7,"luminosity":2.7,"ring":"opposition","orbit_priority":5,"angle":2.0734511513692637,"meaning_summary":"Distortion bends signs, speech, law, and memory away from truth.","polarity":"corruption","relation_to_center":"Twists meaning rather than confronting it honestly.","relation_to_quran":"The Qur’an exposes concealment, manipulation, and crooked interpretation.","relation_to_human_response":"Calls for discernment and truthful reading.","color":"#9f4a4f","glow":22}'),
  ('landing', 'scene_node', 'vector_despair', 37, '{"id":"vector_despair","label":"Despair","type":"corruption_vector","symbolic_role":"Collapse of hope","theological_weight":2.9,"visual_tier":7,"luminosity":2.5,"ring":"opposition","orbit_priority":6,"angle":2.324778563656447,"meaning_summary":"Despair cuts the path of return and magnifies ruin.","polarity":"corruption","relation_to_center":"Forgets mercy and severs hope from the source.","relation_to_quran":"The Qur’an opposes satanic despair with the promise of repentance.","relation_to_human_response":"Warns against surrender to darkness after failure.","color":"#924145","glow":20}'),
  ('landing', 'scene_node', 'worldview_knowledge', 38, '{"id":"worldview_knowledge","label":"Knowledge","type":"worldview_cluster","symbolic_role":"Ways of knowing","theological_weight":5.8,"visual_tier":8,"luminosity":5.8,"ring":"worldview","orbit_priority":1,"angle":-2.42,"meaning_summary":"Knowledge becomes luminous when tethered to truth, humility, and purpose.","polarity":"guidance","relation_to_center":"Receives measure and legitimacy from the source of truth.","relation_to_quran":"The Qur’an orders knowledge around signs, recitation, and wisdom.","relation_to_human_response":"Calls scholars and seekers to sincerity and responsibility.","color":"#93c4ff","glow":24,"linked_cluster_id":"cl_knowledge"}'),
  ('landing', 'scene_node', 'worldview_civilization', 39, '{"id":"worldview_civilization","label":"Civilization","type":"worldview_cluster","symbolic_role":"Collective ordering","theological_weight":5.6,"visual_tier":8,"luminosity":5.6,"ring":"worldview","orbit_priority":2,"angle":-2.14,"meaning_summary":"Civilizations rise or decay through memory, justice, worship, and moral order.","polarity":"warning","relation_to_center":"Civilizational legitimacy depends on alignment with truth and justice.","relation_to_quran":"The Qur’an reads history as morally charged civilizational pattern.","relation_to_human_response":"Calls communities to stewardship rather than arrogance.","color":"#8dbaff","glow":24,"linked_cluster_id":"cl_civilization"}'),
  ('landing', 'scene_node', 'worldview_morality', 40, '{"id":"worldview_morality","label":"Morality","type":"worldview_cluster","symbolic_role":"Ethical ordering","theological_weight":5.8,"visual_tier":8,"luminosity":5.8,"ring":"worldview","orbit_priority":3,"angle":-1.86,"meaning_summary":"Morality is not mood but the patterned response to revelation and creation.","polarity":"guidance","relation_to_center":"Grounded in the character of the source and divine command.","relation_to_quran":"The Qur’an forms moral perception through story, law, and exhortation.","relation_to_human_response":"Calls for virtue, restraint, and accountability.","color":"#86c0ff","glow":24,"linked_cluster_id":"cl_ethics"}'),
  ('landing', 'scene_node', 'worldview_human_nature', 41, '{"id":"worldview_human_nature","label":"Human Nature","type":"worldview_cluster","symbolic_role":"Fitrah and weakness","theological_weight":5.7,"visual_tier":8,"luminosity":5.6,"ring":"worldview","orbit_priority":4,"angle":-1.58,"meaning_summary":"Human nature bears trust, dignity, weakness, forgetfulness, and openness to guidance.","polarity":"restoration","relation_to_center":"Creatureliness and trust derive from the source.","relation_to_quran":"The Qur’an reads the human as both honored and vulnerable.","relation_to_human_response":"Calls for discipline, self-knowledge, and repentance.","color":"#89c9ff","glow":24,"linked_cluster_id":"cl_human_nature"}');

INSERT OR REPLACE INTO wv_landing_atlas_item (atlas_id, section, item_id, sort_order, data_json) VALUES
  ('landing', 'scene_node', 'worldview_education', 42, '{"id":"worldview_education","label":"Education","type":"worldview_cluster","symbolic_role":"Formation and transmission","theological_weight":5.5,"visual_tier":8,"luminosity":5.4,"ring":"worldview","orbit_priority":5,"angle":-1.26,"meaning_summary":"Education transmits memory, language, law, and virtue across generations.","polarity":"guidance","relation_to_center":"Education is legitimate when it serves truthful formation.","relation_to_quran":"The Qur’an trains reading, remembering, reciting, and discerning.","relation_to_human_response":"Calls for pedagogy that shapes character, not only technique.","color":"#8dd8ff","glow":22,"linked_cluster_id":"cl_pedagogy"}'),
  ('landing', 'scene_node', 'worldview_economics', 43, '{"id":"worldview_economics","label":"Economics","type":"worldview_cluster","symbolic_role":"Exchange and provision","theological_weight":5.4,"visual_tier":8,"luminosity":5.2,"ring":"worldview","orbit_priority":6,"angle":-0.92,"meaning_summary":"Economics is a moral field of trust, measure, greed, generosity, and justice.","polarity":"warning","relation_to_center":"Provision is a trust, not an autonomous sphere.","relation_to_quran":"The Qur’an disciplines trade, wealth, debt, charity, and usury.","relation_to_human_response":"Calls for restraint, generosity, honesty, and balance.","color":"#93d6ff","glow":22,"linked_cluster_id":"cl_economics"}'),
  ('landing', 'scene_node', 'worldview_prophecy', 44, '{"id":"worldview_prophecy","label":"Prophecy","type":"worldview_cluster","symbolic_role":"Historical transmission of warning and hope","theological_weight":5.9,"visual_tier":8,"luminosity":5.8,"ring":"worldview","orbit_priority":7,"angle":-0.58,"meaning_summary":"Prophecy interrupts closed worlds with truth, warning, and mercy.","polarity":"guidance","relation_to_center":"A mission emitted from the center.","relation_to_quran":"The Qur’an gathers prophetic history into a unified field.","relation_to_human_response":"Calls for hearing, trust, and reform.","color":"#9ae0ff","glow":24,"linked_cluster_id":"cl_prophecy"}'),
  ('landing', 'scene_node', 'worldview_governance', 45, '{"id":"worldview_governance","label":"Governance","type":"worldview_cluster","symbolic_role":"Authority and responsibility","theological_weight":5.5,"visual_tier":8,"luminosity":5.4,"ring":"worldview","orbit_priority":8,"angle":-0.22,"meaning_summary":"Governance is a test of justice, consultation, trust, and restraint.","polarity":"warning","relation_to_center":"Authority is derivative, never absolute.","relation_to_quran":"The Qur’an disciplines power through justice and accountability.","relation_to_human_response":"Calls rulers and communities to trust and responsibility.","color":"#8fb7ff","glow":22,"linked_cluster_id":"cl_governance"}'),
  ('landing', 'scene_node', 'worldview_language', 46, '{"id":"worldview_language","label":"Language","type":"worldview_cluster","symbolic_role":"Naming and meaning","theological_weight":5.6,"visual_tier":8,"luminosity":5.5,"ring":"worldview","orbit_priority":9,"angle":0.18,"meaning_summary":"Language carries memory, revelation, law, and translation across worlds.","polarity":"guidance","relation_to_center":"Speech is meaningful because reality is not mute.","relation_to_quran":"The Qur’an discloses meaning through recited Arabic yet addresses humanity.","relation_to_human_response":"Calls for truthful naming and careful interpretation.","color":"#9bc3ff","glow":22,"linked_cluster_id":"cl_language"}'),
  ('landing', 'scene_node', 'worldview_spirituality', 47, '{"id":"worldview_spirituality","label":"Spirituality","type":"worldview_cluster","symbolic_role":"Interior life","theological_weight":5.7,"visual_tier":8,"luminosity":5.6,"ring":"worldview","orbit_priority":10,"angle":0.54,"meaning_summary":"Spirituality concerns purification, remembrance, humility, and nearness.","polarity":"restoration","relation_to_center":"The heart lives by relation to the source.","relation_to_quran":"The Qur’an purifies by remembrance, warning, and hope.","relation_to_human_response":"Calls for sincerity, prayer, and inner vigilance.","color":"#8ef2d0","glow":22,"linked_cluster_id":"cl_spirituality"}'),
  ('landing', 'scene_node', 'worldview_memory', 48, '{"id":"worldview_memory","label":"Memory","type":"worldview_cluster","symbolic_role":"Civilizational remembrance","theological_weight":5.4,"visual_tier":8,"luminosity":5.3,"ring":"worldview","orbit_priority":11,"angle":0.9,"meaning_summary":"Memory protects peoples from repeating ruin and losing revelation.","polarity":"restoration","relation_to_center":"Memory is fidelity to what the center discloses.","relation_to_quran":"The Qur’an is remembrance and a restorer of memory.","relation_to_human_response":"Calls for transmission, study, and historical seriousness.","color":"#a4d2ff","glow":22,"linked_cluster_id":"cl_memory"}'),
  ('landing', 'scene_node', 'worldview_justice', 49, '{"id":"worldview_justice","label":"Justice","type":"worldview_cluster","symbolic_role":"Public moral order","theological_weight":5.7,"visual_tier":8,"luminosity":5.5,"ring":"worldview","orbit_priority":12,"angle":1.24,"meaning_summary":"Justice binds law, witness, governance, and economics into a public ethic.","polarity":"guidance","relation_to_center":"A political echo of divine order.","relation_to_quran":"The Qur’an sends justice into every sphere of social life.","relation_to_human_response":"Calls for courage, truth, and collective responsibility.","color":"#8fd5ff","glow":22,"linked_cluster_id":"cl_law"}'),
  ('landing', 'scene_node', 'worldview_hereafter', 50, '{"id":"worldview_hereafter","label":"Hereafter","type":"eschatology_theme","symbolic_role":"Final horizon","theological_weight":5.8,"visual_tier":8,"luminosity":5.8,"ring":"worldview","orbit_priority":13,"angle":1.56,"meaning_summary":"The hereafter gives moral weight, consequence, and proportion to the whole atlas.","polarity":"warning","relation_to_center":"Final judgment belongs to the source.","relation_to_quran":"The Qur’an repeatedly places worldly life under eschatological light.","relation_to_human_response":"Calls for accountability, hope, and fear in balance.","color":"#a0c8ff","glow":24,"linked_cluster_id":"cl_eschatology"}'),
  ('landing', 'scene_node', 'worldview_technology', 51, '{"id":"worldview_technology","label":"Technology","type":"worldview_cluster","symbolic_role":"Mediation and attention","theological_weight":5,"visual_tier":8,"luminosity":5,"ring":"worldview","orbit_priority":14,"angle":1.88,"meaning_summary":"Technology reshapes attention, agency, mediation, and memory.","polarity":"warning","relation_to_center":"Tools remain subordinate to higher ends and truths.","relation_to_quran":"The Qur’an judges techniques by what they serve and what they deform.","relation_to_human_response":"Calls for disciplined attention and ethical mediation.","color":"#8fb0ff","glow":20,"linked_cluster_id":"cl_technology"}'),
  ('landing', 'scene_node', 'worldview_aesthetics', 52, '{"id":"worldview_aesthetics","label":"Aesthetics","type":"worldview_cluster","symbolic_role":"Beauty and form","theological_weight":5.2,"visual_tier":8,"luminosity":5.2,"ring":"worldview","orbit_priority":15,"angle":2.18,"meaning_summary":"Beauty trains perception, gratitude, proportion, and civilizational memory.","polarity":"guidance","relation_to_center":"Beauty reflects order without exhausting it.","relation_to_quran":"The Qur’an shapes aural, poetic, and moral beauty.","relation_to_human_response":"Calls for forms that illuminate rather than distract.","color":"#d4a8ff","glow":20,"linked_cluster_id":"cl_aesthetics"}'),
